import{_ as a,o as r,c as e,a2 as i}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"官方机器人","description":"官方机器人：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/bot-notify.md","filePath":"features/bot-notify.md","lastUpdated":1785020677000}'),l={name:"features/bot-notify.md"};function o(n,t,s,d,h,u){return r(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="官方机器人" tabindex="-1">官方机器人 <a class="header-anchor" href="#官方机器人" aria-label="Permalink to &quot;官方机器人&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>为平台或各区域配置「官方机器人」私信通道，用于系统通知、客服对话，并可开启 AI 自动回复。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li><a href="/features/message">私信与群聊</a> 基础能力已可用。</li><li>若启用 AI 回复：已配置 <a href="/features/ai">AI 中台</a> 供应商与场景路由。</li><li>账号具备 <strong>用户体系 → 官方机器人</strong> 读写权限。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>路径：<strong>用户体系 → 官方机器人</strong></p><h3 id="_1-选择范围" tabindex="-1">1. 选择范围 <a class="header-anchor" href="#_1-选择范围" aria-label="Permalink to &quot;1. 选择范围&quot;">​</a></h3><p>页面顶部可切换：</p><ul><li><strong>平台默认</strong>（region_id=0）：仅服务无区域归属的平台级用户</li><li><strong>具体区域</strong>：通过区域筛选器选择</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>各区域须 <strong>单独初始化</strong>，不会自动继承平台机器人。区域用户只有在本区域 init 后才可与官方机器人私聊。</p></div><h3 id="_2-初始化机器人" tabindex="-1">2. 初始化机器人 <a class="header-anchor" href="#_2-初始化机器人" aria-label="Permalink to &quot;2. 初始化机器人&quot;">​</a></h3><p>在目标区域点击 <strong>「初始化机器人」</strong>：</p><ul><li>系统创建机器人用户并开通私信通道</li><li>初始化前显示「未开通」；成功后显示「已开通」</li></ul><h3 id="_3-编辑配置" tabindex="-1">3. 编辑配置 <a class="header-anchor" href="#_3-编辑配置" aria-label="Permalink to &quot;3. 编辑配置&quot;">​</a></h3><p>点击 <strong>「编辑配置」</strong> 或卡片进入，可设置：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>启用</td><td>关闭后用户无法向该机器人发消息</td></tr><tr><td>首条通知后置顶会话</td><td>系统通知到达时会话置顶</td></tr><tr><td>展示昵称 / 头像</td><td>用户端看到的官方形象</td></tr><tr><td>AI 回复</td><td>开启后用户消息可走 AI 中台自动回复（需 AI 已配置）</td></tr></tbody></table><h3 id="_4-解绑-慎用" tabindex="-1">4. 解绑（慎用） <a class="header-anchor" href="#_4-解绑-慎用" aria-label="Permalink to &quot;4. 解绑（慎用）&quot;">​</a></h3><p><strong>解绑机器人</strong> 仅解除绑定关系，不删除机器人用户账号；一般用于重新 init 前的清理。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>官方机器人 <strong>严格按区域隔离</strong>：</p><table tabindex="0"><thead><tr><th>场景</th><th>操作</th></tr></thead><tbody><tr><td>新区域上线</td><td>进入该区域 → 初始化机器人 → 启用</td></tr><tr><td>仅平台用户</td><td>只配置「平台默认」即可</td></tr><tr><td>关闭某区域官方私信</td><td>编辑该区域配置并关闭「启用」</td></tr></tbody></table><p>与 <strong>区域管理 → 区域列表</strong> 中「关闭私信」配合：关闭区域私信后，用户可能仅能与官方机器人通信（以区域列表说明为准）。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>在测试区域完成 <strong>初始化机器人</strong> 并 <strong>启用</strong>。</li><li>客户端该区域的「消息」中出现与官方机器人的会话，发送文字能收到回复（人工或 AI）。</li><li>后台卡片显示「已开通」「已启用」；若开 AI，标签显示「AI回复」。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>初始化按钮灰色或不可用</strong></p><ul><li>当前区域已 init；或账号无写权限。</li><li>该区域已有配置时改用「编辑配置」。</li></ul><p><strong>用户看不到官方机器人</strong></p><ul><li>该区域未 init 或未启用。</li><li>区域 <strong>私信</strong> 被关闭且业务规则限制入口。</li></ul><p><strong>AI 回复不工作</strong></p><ul><li>确认编辑配置中 <strong>AI 回复</strong> 已开启。</li><li>检查 <a href="/features/ai">AI 中台</a> 供应商余额、场景路由是否包含机器人对话场景。</li></ul><p><strong>与智能评论机器人的区别</strong></p><ul><li><strong>官方机器人</strong>（本页）：系统通知、客服私信。</li><li><strong>评论运营 → 智能评论机器人</strong>：在笔记下自动评论，二者账号与配置独立。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/message">私信与群聊</a></li><li><a href="/features/ai">AI 中台</a></li><li><a href="/features/notification">通知与推送</a></li></ul>',36)])])}const b=a(l,[["render",o]]);export{c as __pageData,b as default};
